from taf.internal.aliasing import aliasing_scope
from taf.sw.neat.facade import NEATConnection
from taf.sw.neat.deprecate import deprecated


class neat(object):
    ROBOT_LIBRARY_SCOPE = "TEST SUITE"
    lookup_handler, store = aliasing_scope('neat_connection', name=__name__)

    def __init__(self):
        self.lookup_handler.store = self.store

    def connect_to(self, host, username, password, neat_version='neat_v1', alias='default', timeout=60):
        """
        Provides connection and authorization to NEAT.

        :param str host: IP address to proper NEAT host.
        :param str username: Username to authenticate to NEAT.
        :param str password: Password to authenticate to NEAT.
        :param str neat_version: (Optional) NEAT RESTAPI version, default is neat_v1.
        :param str alias: (Optional) Name of the connection. It not provided, this connection becomes default.
        :param Union[int,str] timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: None
        """
        neat_connection = NEATConnection(host, username, password, neat_version, int(timeout))
        self.store.add(neat_connection, alias)

    @lookup_handler.implicit_lookup
    def disconnect(self, neat_connection=None, timeout=60):
        """
        Disconnect the connection.

        :param NEATConnection neat_connection: string name alias if used.
        :param Union[int,str] timeout: Optional, timeout in seconds for request, default is '60s'.
        :return: None
        """
        neat_connection.disconnect(timeout=int(timeout))
        self.store.remove_object(neat_connection)

    @lookup_handler.implicit_lookup
    def get_cloud_resources(self, neat_connection=None, timeout=60, **kwargs):
        """
        get cloud resources.

        :param NEATConnection neat_connection: string name alias if used.
        :param Union[int,str] timeout: Optional, timeout in seconds for request, default is '60s'.
        The following are part of kwargs:
        :param boolean raw: Optional, turns off OpenAPI deserialization. Default is False.
        :param list names: Optional, cloud names, i.e. ['OE22-SNO-10-108-218-141']
        :param list states: Optional, states of a cloud, i.e ['online']
        :param list tags: Optional, List of tags
        :param list fields: Optional, Limit cloud attributes that are returned in response.
                            Available values : tags, cloudId, name, description, cloudOamHost, resources, groups, created, updated, groups, product,
                            project, alarms, swInfo, hwPorts, status, useTls, secretId.
                            i.e. fields=['secretId']
        :param str limit: Optional, Limit query results or define page size.
                          Without the limit query parameter, the maximum response is 20 resources.
                          If giving the limit parameter, as many as specified resources in the parameter will be returned.
        :return Dict: containing meta dict and data list, detailed response please refer to
                      https://gitlabe2.ext.net.nokia.com/ucim/ucim/-/blob/master/apis/rest/cloud/doc/openapi.yaml#/clouds/get_clouds

                    ::

                        {
                          "meta": {
                            "count": 1,
                            "limit": 20,
                            "offset": 0,
                            "total": 1
                          },
                          "data": [
                            {
                              "type": "clouds",
                              "id": "42aa1265-cc5f-455c-8118-358e734f7c5b",
                              "attributes": {
                                "cloudId": "42aa1265-cc5f-455c-8118-358e734f7c5b",
                                "cloudType": "k8s",
                                "name": "OE22-SNO-10-108-218-141",
                                "cloudOamHost": "oe22-sno-10-108-218-141.ocp.hz.nsn-rdnet.net",
                                "useTls": true,
                                "product": "openshift",
                                "project": "admin",
                                "created": "2023-09-12T03:58:47Z",
                                "updated": "2023-09-12T03:58:56Z",
                                "groups": [],
                                "tags": [
                                  "OE22-SNO-10-108-218-141"
                                ],
                                "alarms": {
                                  "collectionSuccessful": false,
                                  "lastCollectionTimestamp": null,
                                  "alarms": []
                                },
                                "vm": null,
                                "hwPorts": {},
                                "secretId": "328a128c-cb1c-4af3-856e-4eaf479c1b7e"
                              }
                            }
                          ]
                        }
        """
        return neat_connection.get_cloud_resources(timeout=int(timeout), **kwargs)

    @lookup_handler.implicit_lookup
    def get_secrets_by_secretid(self, secret_id, fields=None, neat_connection=None, timeout=60, **kwargs):
        """
        Get a cloud secret by secret id.

        :param str secret_id: globally unique identifier for secret resource.
        :param list fields: Limit secret attributes that are returned in response.
                            Available values : kubernetesAccess, sshAccess, credentials.
                            Default is None which means all of the three secrets will be returned.
        :param NEATConnection neat_connection: string name alias if used.
        :param Union[int,str] timeout: Optional, timeout in seconds for request, default is '60s'.
        :return dict: secrets including kubernetesAccess, sshAccess, credentials.

                ::

                     {
                      "kubernetesAccess": {
                        "kubeconfig": "YXBpVmVyc2lvbjogdjEKY2x1c3RlcnM6Ci0gY2x1c3RlcjoKICAgIGNlcnRpZmljYXRl"
                        },
                      "sshAccess": {},
                      "credentials": {
                        "username": "a3ViZWFkbWlu",
                        "password": "UElueXQtaW52dngtVlNCQ3QtYmVIdVQ="
                      }
                    }
        """
        return neat_connection.get_secrets_by_secretid(secret_id=secret_id, fields=fields, timeout=int(timeout), **kwargs)

