    @lookup_handler.implicit_lookup
    def create_edgedc_by_json_plan(self, edgedc_plan, neat_connection=None, raw=True, timeout=60, **kwargs):
        """
        Create edgedc resources by json plan file.

        .. admonition:: API used:

            POST `/neat/api/edgedc-manager/v1/edgedcs`_

            .. _/neat/api/edgedc-manager/v1/edgedcs:
             https://gitlabe2.ext.net.nokia.com/ucim/site-manager/-/blob/26.1.0-7/apis/northbound/doc/openapi.yaml#/edgedcs/post_edgedcs

        :param dict edgedc_plan: edgedc plan contents.
        :param NEATConnection neat_connection: string name alias if used.
        :param boolean raw: Optional, turns off OpenAPI deserialization.
        :param Union[int,str] timeout: Optional, timeout in seconds for request.

        Return value example: create_edgedc_by_json_plan.json_
            .. _create_edgedc_by_json_plan.json: ../example/response_examples.html#create-edgedc-by-json-plan-json

        .. note::
            The example file shows the full API response (including 'meta' and 'data' keys),
            but this keyword returns only the value under the 'data' key.

        .. admonition:: Robot examples:
            :collapsible: closed

            - Create EdgeDC by JSON plan::

                | ${egdedc_contents}= | Get File                              | ${EDGEDC_JSON_PATH}          |
                | ${edgedc_plan}=     | Evaluate                              | json.loads($egdedc_contents) |
                | ...                 | modules=json                          |
                | ${res}=             | myneat.Create Edgedc By Json Plan     | edgedc_plan=${edgedc_plan} |
        """
        return neat_connection.create_edgedc_by_json_plan(edgedc_plan=edgedc_plan, raw=raw, timeout=int(timeout), **kwargs)

